ruleContent.nextContentUrl:
@js:
if (result.indexOf("next.png") > -1) {

	code = result.match(/eval\(function(.*)\);/)[0]
	code = code.replace(/u[0-9a-f]{10,}/, 'uData')
	eval(code)

	if(!uData.match('_')) {
	 next = java.getElement("@@class.ud-link ud-link1@span@a")
	 uData = next.attr("href")
	}
	uData
}

