    }
});

push("书籍分类", null, 1);

const tag = org.jsoup.Jsoup.parse(Ajax(source.key + "/novels/hot")).select('.listleft li:not([class]) a');
const sort = [
    ["全部", "monthvisit_0_0_1"],
    ["连载", "newhot_0_0_1"],
    ["全本", "newhot_0_1_1"],
    ["人气", "weekvisit_0_0_1"],
    ["推荐", "allvote_0_0_1"],
    ["新书", "newhot_0_0_1"]
];

sort.forEach(([name, pattern]) => {
    let Url = pattern.replace(/1$/, "{{page}}");
    push(`༺ˇ»\`ʚ  ${name}  ɞ´«ˇ༻`, Url, 1);
    tag.toArray().forEach((e, i) => push(e.text(), Url.replace(/^(.+?_)0/, `$1${i+1}`), 0.25));
});

push("༺ˇ»`ʚ  标签  ɞ´«ˇ༻", null, 1);
