let ck = cookie.getCookie(url).split('; ').filter(item => !item.startsWith("jieqiVisitTime")).join('; ');
cookie.setCookie(url, ck);
if (result.code() == 403) java.toast('服务器拒绝访问，请检查网络状况！');
if (Regex.test(original.body())) {
	   cookie.removeCookie(url);
    result = java.startBrowserAwait(url, "验证");
    if (/onloadTurnstileCallback/.test(original.body())) {
    java.initUrl();
    result = java.getStrResponse(null, null, false);
    }
}
result;

