function cfCheck(html, targetUrl) {
  var text = String(html || '');
  if (/Just a moment|cf-turnstile|onloadTurnstileCallback|challenges\.cloudflare\.com/i.test(text)) {
    java.longToast('请按网页提示完成人机验证；若无限循环，请检查 WebView 与请求头 UA 版本。');
    return java.startBrowserAwait(targetUrl, '69书吧人机验证').body();
  }
  return html;
}

